import React, { useState, useEffect } from 'react';

const PageVisitCounter = () => {
    const [visits, setVisits] = useState(0);

    useEffect(() => {
        // Use your domain name to create a unique namespace
        const namespace = "infinitylbsl.com.np";
        const key = "homepage";

        fetch(`https://api.countapi.xyz/hit/${namespace}/${key}`)
            .then((res) => res.json())
            .then((data) => {
                setVisits(data.value);
            })
            .catch((err) => console.error("Counter Error:", err));
    }, []);

    const counterStyle = {
        padding: '10px',
        fontSize: '0.9rem',
        color: '#1e3c72',
        fontWeight: 'bold',
        textAlign: 'center',
        background: '#f1f1f1',
        borderRadius: '5px',
        display: 'inline-block',
        marginTop: '10px'
    };

    return (
        <div style={counterStyle}>
            Total Page Visits: <span style={{color: '#00a86b'}}>{visits}</span>
        </div>
    );
};

export default PageVisitCounter;
